Bước 5 - Khung T-SQL:
```sql
BEGIN TRY
  BEGIN TRANSACTION;
    IF (SELECT SoDu FROM TAIKHOAN WHERE SoTK='A') < 5000000
       THROW 50001, N'Không đủ số dư', 1;
    UPDATE TAIKHOAN SET SoDu = SoDu - 5000000 WHERE SoTK='A';
    UPDATE TAIKHOAN SET SoDu = SoDu + 5000000 WHERE SoTK='B';
  COMMIT TRANSACTION;
END TRY
BEGIN CATCH
  ROLLBACK TRANSACTION;
  THROW;
END CATCH
```
